document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function s(n,e,s,t="info"){return`\n      <div class="insight-card ${t}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${s}</div>\n      </div>\n    `}const t=document.getElementById("gym-form"),i=document.getElementById("gym-result");t&&t.addEventListener("submit",function(t){t.preventDefault();const a=parseInt(document.getElementById("gym-area").value),r=parseFloat(document.getElementById("property-cost").value),o=parseFloat(document.getElementById("equipment-cost").value),l=parseFloat(document.getElementById("renovation-cost").value),d=parseFloat(document.getElementById("additional-costs").value),c=parseFloat(document.getElementById("monthly-fee").value),p=parseInt(document.getElementById("target-members").value),v=parseFloat(document.getElementById("retention-rate").value),m=parseFloat(document.getElementById("personal-training-rate").value),u=parseInt(document.getElementById("personal-sessions").value),g=parseFloat(document.getElementById("rent-cost").value),b=parseFloat(document.getElementById("staff-costs").value),y=parseFloat(document.getElementById("utilities").value),w=parseFloat(document.getElementById("marketing").value),$=parseFloat(document.getElementById("other-expenses").value);if(a<=0||c<=0||p<=0||v<=0)return i.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const h=r+o+l+d,f=p*(v/100),k=f*c,F=u*m,I=.08*k,E=k+F+I,B=g+b+y+w+$,M=E-B,x=12*M,P=M/E*100,D=h/x,R=x/h*100,A=k/f||0,C=E/a,L=f/a,q=f/(a/100)*100,S=12*w/(.3*p),z=B/c,O=f/p*100;let T="info";M<0?T="warning":P>25&&(T="success");let U="info";R<20?U="warning":R>35&&(U="success");let V="info";q<50?V="warning":q>80&&(V="success"),i.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🏋️ Gym Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${s("💰 Total Investment",n(h),"Initial capital required","info")}\n            ${s("📈 Monthly Profit",n(M),`Margin: ${e(P)}`,T)}\n            ${s("⏱️ Payback Period",`${D.toFixed(1)} years`,`ROI: ${e(R)}`,D<=4?"success":"warning")}\n            ${s("👥 Active Members",f.toFixed(0),`Fill Rate: ${e(O)}`,V)}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Facility (purchase/down payment)</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Equipment & machines</span>\n                  <span>${n(o)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Renovation & design</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Additional costs</span>\n                  <span>${n(d)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(h)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Monthly Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Memberships (${f.toFixed(0)} members × $${c})</span>\n                  <span>${n(k)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Personal training (${u} sessions)</span>\n                  <span>${n(F)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Additional services & retail</span>\n                  <span>${n(I)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Revenue</strong></span>\n                  <span><strong>${n(E)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Facility rent</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Staff (trainers, front desk)</span>\n                  <span>${n(b)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Utilities</span>\n                  <span>${n(y)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Marketing & advertising</span>\n                  <span>${n(w)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Other expenses</span>\n                  <span>${n($)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(B)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>📊 Facility Efficiency</h6>\n              <div class="metric-subtitle">\n                Revenue per sq ft: <strong>${n(C)}/month</strong><br>\n                Members per sq ft: <strong>${L.toFixed(3)}</strong><br>\n                Capacity utilization: <strong>${e(q)}</strong>\n              </div>\n            </div>\n            <div class="insight-card ${M>0?"success":"warning"}">\n              <h6>👥 Membership Analysis</h6>\n              <div class="metric-subtitle">\n                Revenue per member: <strong>${n(A)}/month</strong><br>\n                Break-even members: <strong>${z.toFixed(0)} members</strong><br>\n                Acquisition cost: <strong>${n(S)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${M>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(x)}</strong><br>\n                Weekly profit: <strong>${n(x/52)}</strong><br>\n                Daily profit: <strong>${n(x/365)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>💡 Growth Potential</h6>\n              <div class="metric-subtitle">\n                Max revenue (100% capacity): <strong>${n(12*(p*c+F+I))}/year</strong><br>\n                Growth reserve: <strong>${e(100-O)}</strong><br>\n                Potential additional revenue: <strong>+${n((p-f)*c*12)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${P<15?"<li>⚠️ Low profitability. Consider increasing membership fees or reducing costs.</li>":""}\n              ${q<50?"<li>📍 Low utilization. Improve marketing or adjust pricing strategy.</li>":""}\n              ${D>5?"<li>⏰ Long payback period. Optimize startup costs or increase revenue.</li>":""}\n              ${q>85?"<li>✅ High utilization! Consider rate increases or facility expansion.</li>":""}\n              ${P>30?"<li>🎉 Excellent profitability! Consider opening additional locations.</li>":""}\n              <li>🏋️ Develop personal training services - they provide highest margins (50-70%).</li>\n              <li>📱 Implement fitness app for booking, tracking, and member engagement.</li>\n              <li>🎯 Create specialized programs: women's fitness, functional training, senior fitness.</li>\n              <li>🤝 Develop corporate wellness programs for stable revenue.</li>\n              <li>💊 Add supplement and fitness accessory sales for additional revenue.</li>\n              <li>⭐ Invest in member retention - it's cheaper than acquiring new members.</li>\n              <li>📈 Implement tiered membership pricing: basic, premium, VIP options.</li>\n              <li>🌟 Regularly update equipment and introduce new fitness programs.</li>\n              <li>🏆 Create member challenges and rewards programs to boost engagement.</li>\n              <li>📊 Use data analytics to optimize class schedules and equipment usage.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.gymBusinessData={"Gym Area (sq ft)":a,"Total Investment ($)":h,"Target Members":p,"Effective Members":f.toFixed(0),"Monthly Revenue ($)":E,"Monthly Expenses ($)":B,"Monthly Profit ($)":M,"Annual Profit ($)":x,"Profit Margin (%)":P,"Annual ROI (%)":R,"Payback Period (years)":D,"Revenue per Member ($)":A,"Capacity Utilization (%)":q,"Break-even Members":z.toFixed(0)}}),window.downloadCSV=function(){if(!window.gymBusinessData)return;const n=Object.entries(window.gymBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),s=document.createElement("a");s.href=URL.createObjectURL(e),s.download="gym-business-plan.csv",s.click()}});